import * as THREE from 'three';
import {autoFitOrthographicBounds} from '../camera-fit.js';
import {disposeToyTree} from '../world/toy-kit.js';
import {BASEBALL} from './baseball-court.js';
import {batFrame,BAT_PROFILE,BAT_CONTACT} from './baseball-frame.js';
export function createBat(){const root=new THREE.Group();root.name='baseball.bat';const profile=BAT_PROFILE.map(([u,r])=>new THREE.Vector2(r,u));const bat=new THREE.Mesh(new THREE.LatheGeometry(profile,24),new THREE.MeshStandardMaterial({color:'#dfbb83',roughness:.78}));bat.rotation.z=-Math.PI/2;root.add(bat);bat.castShadow=true;for(const u of[-.16,-.09,-.02,.05,.12]){const band=new THREE.Mesh(new THREE.TorusGeometry(.022,.004,6,20),new THREE.MeshStandardMaterial({color:'#739a91',roughness:.85}));band.rotation.y=Math.PI/2;band.position.x=u;root.add(band);}return root;}
function flightBall(){const root=new THREE.Group();root.name='baseball.flight-ball';const m=new THREE.Mesh(new THREE.SphereGeometry(.09,20,14),new THREE.MeshStandardMaterial({color:'#fff8e2',roughness:.72}));root.add(m);for(const sign of[-1,1])for(let i=0;i<12;i++){const t=(i/11-.5)*Math.PI*1.3,p=new THREE.Vector3(sign*.045,Math.sin(t)*.074,Math.cos(t)*.074),stitch=new THREE.Mesh(new THREE.CapsuleGeometry(.003,.018,3,6),new THREE.MeshStandardMaterial({color:'#b96654',roughness:.8}));stitch.position.copy(p);stitch.rotation.z=sign*.65;root.add(stitch);}return root;}
export function createBaseballSession({view,player,model,poser}){
 if(!view?.root||!player||!model||!poser)throw Error('Baseball actors unavailable');const root=view.root,saved={p:player.position.clone(),q:player.quaternion.clone(),s:player.scale.clone(),mp:model.position.clone(),mq:model.quaternion.clone(),ms:model.scale.clone(),pose:poser.getState(),children:player.children.map(n=>[n,n.visible])},lease=view.acquireResidentActivity?.('baseball-tiger');if(!lease)throw Error('Tiger unavailable');let alive=true,enter=0;
 const props=new THREE.Group();props.name='baseball.session';model.add(props);const bat=createBat(),ball=flightBall();props.add(bat,ball);const target=new THREE.Mesh(new THREE.TorusGeometry(.20,.012,7,36),new THREE.MeshBasicMaterial({color:'#fff2b6',transparent:true,opacity:.8}));target.position.set(BAT_CONTACT[0],.01,BAT_CONTACT[2]);target.rotation.x=-Math.PI/2;props.add(target);
 function place(){root.updateWorldMatrix(true,false);const b=BASEBALL.batter,p=root.localToWorld(new THREE.Vector3(b.x,b.y,b.z));if(player.parent)player.parent.worldToLocal(p);player.position.copy(p);const q=root.getWorldQuaternion(new THREE.Quaternion()).multiply(new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0,1,0),b.yaw));if(player.parent)q.premultiply(player.parent.getWorldQuaternion(new THREE.Quaternion()).invert());player.quaternion.copy(q);}
 let release;
 function update(s,reduced=false,dt=.05){if(!alive)return;enter=Math.min(1,enter+Math.max(0,dt)/.32);place();model.position.set(0,0,0);model.quaternion.identity();poser.setPose('bat',enter,s.swingPhase);const f=batFrame(s.swingPhase);bat.position.fromArray(f.grip);bat.rotation.y=-f.angle;ball.position.fromArray(s.ball);ball.visible=s.ballVisible;ball.rotation.set(s.elapsed*3,s.elapsed*4,0);target.visible=s.phase==='flight'&&!s.hasSwung;target.material.opacity=.65;lease.pose({...BASEBALL.pitcher,pitchPhase:s.pitchPhase??(s.phase==='ready'?0:1),showBall:['ready','windup'].includes(s.phase)});player.updateWorldMatrix(true,true);}
 function dispose(){if(!alive)return;alive=false;disposeToyTree(props);lease.release();player.position.copy(saved.p);player.quaternion.copy(saved.q);player.scale.copy(saved.s);model.position.copy(saved.mp);model.quaternion.copy(saved.mq);model.scale.copy(saved.ms);try{poser.setPose(saved.pose.name,saved.pose.amount,saved.pose.time);}finally{for(const[n,v]of saved.children)n.visible=v;player.updateWorldMatrix(true,true);}}
 try{player.scale.setScalar(1);model.scale.setScalar(1);model.position.set(0,0,0);model.quaternion.identity();for(const[n]of saved.children)if(n!==model)n.visible=false;place();poser.setPose('bat',0,0);lease.pose({...BASEBALL.pitcher,pitchPhase:.5,showBall:false});player.updateWorldMatrix(true,true);lease.model.updateWorldMatrix(true,true);release=model.worldToLocal(lease.model.userData.parts.Ball.getWorldPosition(new THREE.Vector3())).toArray();update({phase:'ready',swingPhase:0,ball:release,ballVisible:false,pitchPhase:0,elapsed:0},true,0);}catch(e){dispose();throw e;}
 return{release,update,dispose,tigerUUID:lease.model.uuid,props};
}
export function fitBaseballCamera(camera,root,viewport){root.updateWorldMatrix(true,false);camera.position.copy(root.localToWorld(new THREE.Vector3(.6,7.8,-4.4)));camera.up.set(0,1,0);camera.lookAt(root.localToWorld(new THREE.Vector3(0,1,-13.1)));camera.updateMatrixWorld(true);const b=new THREE.Box3(new THREE.Vector3(-4.35,.01,-17.7),new THREE.Vector3(4.1,3.25,-10.6)).applyMatrix4(root.matrixWorld);autoFitOrthographicBounds({camera,worldBounds:b,viewport,paddingPx:{top:10,right:10,bottom:10,left:10}});camera.updateMatrixWorld(true);return b;}
